//! Lightweight game client code generation for the Rust shell.
//!
//! Emits the `src/bin/game.rs` entry point that launches the egui-based
//! game client using `orbital_client::run_game`.

/// Generate the `src/bin/game.rs` source for the generated application.
pub fn generate_game_bin() -> String {
    r#"//! Lightweight game client entry point.
//!
//! Generated by the Orbital Rust shell. Run with:
//!   cargo run --bin game
//!
//! The game client communicates with the Orbital server (default
//! http://127.0.0.1:3030) using the closed-circuit event protocol.

use std::path::Path;

fn main() -> anyhow::Result<()> {
    let server_url = std::env::var("SERVER_URL")
        .ok()
        .or_else(|| Some("http://127.0.0.1:3030".to_string()));

    orbital_client::run_game(Path::new("resolved.orb"), server_url.as_deref())
}
"#
    .to_string()
}
